pub fn check_disconnected(_n: i8, _m: i8, horizontal: &Vec<char>, vertical: &Vec<char>) -> bool {
    // Based solely on corner arrows:
    // (left, top)    => horizontal[0],  vertical[0]
    // (left, bottom) => horizontal[0],  vertical[m-1]
    // (right, top)   => horizontal[n-1], vertical[0]
    // (right, bottom)=> horizontal[n-1], vertical[m-1]
    let h0 = horizontal[0];
    let h1 = horizontal[horizontal.len() - 1];
    let v0 = vertical[0];
    let v1 = vertical[vertical.len() - 1];

    (h0 == '>' && v0 == 'v')
        || (h0 == '<' && v1 == 'v')
        || (h1 == '>' && v0 == '^')
        || (h1 == '<' && v1 == '^')
}

pub fn solve(n: i8, m: i8, horizontal: Vec<char>, vertical: Vec<char>) -> Vec<char> {
    // Constraints say 2..=20, but we defensively ensure indexing is safe.
    assert!(n >= 2 && m >= 2);
    assert!(horizontal.len() == n as usize);
    assert!(vertical.len() == m as usize);

    if check_disconnected(n, m, &horizontal, &vertical) {
        vec!['N', 'O', '\n']
    } else {
        vec!['Y', 'E', 'S', '\n']
    }
}